                                                    "value": {
                                                        "type": "string",
                                                        "minLength": 1,
                                                        "maxLength": 255
                                                    }
                                                },
                                                "additionalProperties": false
                                            },
                                            "maxItems": 100
                                        }
                                    },
                                    "required": [
                                        "name",
                                        "mode"
                                    ],
                                    "additionalProperties": false
                                },
                                "maxItems": 256
                            }
                        },
                        "additionalProperties": false
                    }
                },
                "required": [
                    "name",
                    "dataType"
                ],
                "additionalProperties": false
            },
            "maxItems": 256
        },
        "deviceClass": {
            "type": "string",
